-- 029: Plats för de fem grupper som saknade det (uppslaget i gruppernas beskrivningar, hemsidor och OpenStreetMap).
-- Bara det som saknas fylls i. Stad = kommunen, som för övriga grupper.
update public.groups set country = coalesce(country, 'Sverige'), city = coalesce(nullif(city, ''), 'Simrishamn'), region = coalesce(region, 'Skåne län'), postcode = coalesce(postcode, '276 35'), address = coalesce(address, 'Borrby'), lat = coalesce(lat, 55.4580331), lng = coalesce(lng, 14.1808853) where id = 'bc378e1f-d4d8-45d7-b17c-8415494417bc';   -- Kvarnen Borrby
update public.groups set country = coalesce(country, 'Sverige'), city = coalesce(nullif(city, ''), 'Tranemo'), region = coalesce(region, 'Västra Götalands län'), address = coalesce(address, 'Strömsfors, Uddebo'), lat = coalesce(lat, 57.4739744), lng = coalesce(lng, 13.2653900) where id = '9dfc4d9e-b3b8-41f1-acf8-feb8b7d445eb';   -- Byar och kvarter (Casablanca bogemenskap)
update public.groups set country = coalesce(country, 'Sverige'), city = coalesce(nullif(city, ''), 'Orust'), region = coalesce(region, 'Västra Götalands län'), postcode = coalesce(postcode, '474 31'), address = coalesce(address, 'Husebybergen, Ellös'), lat = coalesce(lat, 58.1799703), lng = coalesce(lng, 11.4687475) where id = '0378825e-672b-432f-a2ba-e50a75822043';   -- Husebybergens egnahemsförening
update public.groups set country = coalesce(country, 'Sverige'), city = coalesce(nullif(city, ''), 'Norrtälje'), region = coalesce(region, 'Stockholms län'), postcode = coalesce(postcode, '764 31'), address = coalesce(address, 'Älmsta, Väddö'), lat = coalesce(lat, 59.9717072), lng = coalesce(lng, 18.8031423) where id = 'b1ac8476-78f8-4e9c-b0f7-76a86c5cee47';   -- Solhem Kollektivhus (Förenade Solhem)
update public.groups set country = coalesce(country, 'Sverige'), city = coalesce(nullif(city, ''), 'Stockholm'), region = coalesce(region, 'Stockholms län'), postcode = coalesce(postcode, '125 31'), address = coalesce(address, 'Älvsjö'), lat = coalesce(lat, 59.2785472), lng = coalesce(lng, 18.0110890) where id = '17d7d42a-7b57-403f-98a0-91a7943d22a1';   -- Kollektivhuset Kupan
select count(*) filter (where city is null and not locked) as grupper_utan_plats from public.groups;
